    private static void assertSprite269TimingMatrix(VqsvIntroDemo.Scene s) {
        SpriteAnim anim = SpriteAnim.load(269);
        if (anim.data.frames.length != 30 || anim.data.cells.length != 54 || anim.data.anim.length != 5) {
            throw new IllegalStateException("Sprite 269 source matrix mismatch frames="
                    + anim.data.frames.length + " cells=" + anim.data.cells.length
                    + " anims=" + anim.data.anim.length);
        }
        short[][] expected = new short[][]{
                {1, 1, 1, 2, 1, 3, 1, 4, 1, 5, 1, 6, 1, 7, 1, 8},
                {1, 9},
                {1, 10, 1, 11, 2, 12, 2, 13, 1, 14, 1, 15, 1, 14, 1, 16, 1, 14, 1, 15,
                        1, 14, 1, 16, 1, 14, 1, 15, 1, 14, 1, 16, 2, 17, 2, 12, 2, 18, 1, 10},
                {1, 19, 1, 20, 1, 21, 1, 22, 1, 23, 1, 24, 1, 25, 1, 26, 1, 27, 1, 28, 5, 23},
                {1, 29, 1, 30, 1, 31, 1, 32, 1, 33, 3, 34, 1, 35, 1, 36, 1, 37, 1, 38,
                        1, 39, 1, 40, 1, 39, 1, 41, 1, 39, 1, 40, 1, 39, 1, 41, 1, 39, 1, 40,
                        1, 39, 1, 41, 1, 42, 1, 37, 1, 43, 1, 35, 1, 44, 1, 45, 1, 46, 1, 47,
                        1, 48, 1, 49, 1, 50, 1, 51, 1, 52, 1, 53, 1, 48}
        };
        int[] sourceTicks = new int[expected.length];
        for (int i = 0; i < expected.length; i++) {
            if (!java.util.Arrays.equals(anim.data.anim[i], expected[i])) {
                throw new IllegalStateException("Sprite 269 anim state " + i
                        + " mismatch expected=" + java.util.Arrays.toString(expected[i])
                        + " actual=" + java.util.Arrays.toString(anim.data.anim[i]));
            }
            for (int j = 0; j < expected[i].length; j += 2) {
                sourceTicks[i] += Math.max(1, expected[i][j]);
            }
        }
        int[] expectedTicks = new int[]{8, 1, 25, 15, 39};
        if (!java.util.Arrays.equals(sourceTicks, expectedTicks)) {
            throw new IllegalStateException("Sprite 269 source tick totals mismatch expected="
                    + java.util.Arrays.toString(expectedTicks)
                    + " actual=" + java.util.Arrays.toString(sourceTicks));
        }
        s.sourceStateTrace.add("SMOKE verified sprite269 source anim matrix q0..q4 frames=[8,1,20,11,37]"
                + " sourceTicks=" + java.util.Arrays.toString(sourceTicks)
                + " sourceEndCheck=game.d.e() q>=r-1, tick=game.d.d()");
    }

    private static void tickUntilAnyBattleState(VqsvIntroDemo.Scene s, int maxTicks, String... stateNames) {
        int guard = 0;
        while (!isBattleState(s, stateNames) && guard++ < maxTicks) {
            if ("P20".equals(s.battleStateName)) {
                s.press0();
            }
            s.tick();
        }
        if (!isBattleState(s, stateNames)) {
            throw new IllegalStateException("Battle states " + java.util.Arrays.toString(stateNames)
                    + " not reached in " + maxTicks + " ticks, current=" + s.battleStateName
                    + " trace=" + tailTrace(s, 10));
        }
    }

    private static boolean isBattleState(VqsvIntroDemo.Scene s, String... stateNames) {
        for (String stateName : stateNames) {
            if (stateName.equals(s.battleStateName)) {
                return true;
            }
        }
        return false;
    }

    static boolean traceContains(VqsvIntroDemo.Scene s, String needle) {
        for (String line : s.sourceStateTrace) {
            if (line.contains(needle)) {
                return true;
            }
        }
        return false;
    }

    static boolean traceContainsAll(VqsvIntroDemo.Scene s, String... needles) {
        for (String line : s.sourceStateTrace) {
            boolean ok = true;
            for (String needle : needles) {
                if (!line.contains(needle)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return true;
            }
        }
        return false;
    }

    private static int traceIndex(VqsvIntroDemo.Scene s, String needle) {
        for (int i = 0; i < s.sourceStateTrace.size(); i++) {
            if (s.sourceStateTrace.get(i).contains(needle)) {
                return i;
            }
        }
        return -1;
    }

    static int latestTraceDamage(VqsvIntroDemo.Scene s, String needle) {
        for (int i = s.sourceStateTrace.size() - 1; i >= 0; i--) {
            String line = s.sourceStateTrace.get(i);
            if (!line.contains(needle)) {
                continue;
            }
            int at = line.indexOf("damage=");
            if (at < 0) {
                return -1;
            }
            int start = at + "damage=".length();
            int end = start;
            while (end < line.length() && Character.isDigit(line.charAt(end))) {
                end++;
            }
            if (end == start) {
                return -1;
            }
            return Integer.parseInt(line.substring(start, end));
        }
        return -1;
    }

    private static int traceCount(VqsvIntroDemo.Scene s, String needle) {
        int count = 0;
        for (String line : s.sourceStateTrace) {
            if (line.contains(needle)) {
                count++;
            }
        }
        return count;
    }

    static void tickUntilTraceContains(VqsvIntroDemo.Scene s, String needle, int maxTicks) {
        int guard = 0;
        while (!traceContains(s, needle) && guard++ < maxTicks) {
            if (s.text != null && s.text.readyForKey) {
                s.press0();
            }
            s.tick();
        }
        if (!traceContains(s, needle)) {
            throw new IllegalStateException("Trace not reached: " + needle
                    + " in " + maxTicks + " ticks, state=" + s.battleStateName
                    + " ui=" + s.battleUiMode
                    + " trace=" + tailTrace(s, 24));
        }
    }

    private static int sourceExpectedExpAward(int enemyLevel, int enemyQuality,
                                              int participantLevel, int participantCount) {
        return sourceExpectedExpAward(enemyLevel, enemyQuality, participantLevel, participantCount, 1000);
    }

    private static int sourceExpectedExpAward(int enemyLevel, int enemyQuality,
                                              int participantLevel, int participantCount,
                                              int divisor) {
        int[] aG = {10, 11, 12, 13, 15};
        int[] aH = {10, 12, 13, 14, 15, 16};
        int[] aI = {105, 100, 80, 60, 40, 20, 5};
        int quality = Math.max(1, Math.min(5, enemyQuality));
        int count = Math.max(1, Math.min(6, participantCount));
        int base = (((enemyLevel << 1) * enemyLevel + 50) * aG[quality - 1] / 10) + 400;
        int diff = Math.max(1, participantLevel) - enemyLevel;
        int levelFactor;
        if (diff >= 6) {
            levelFactor = aI[6];
        } else if (diff > 0) {
            levelFactor = aI[diff];
        } else if (diff == 0) {
            levelFactor = aI[1];
        } else {
            levelFactor = aI[0];
        }
        return Math.max(0, base / count * aH[count - 1] * levelFactor / Math.max(1, divisor));
    }

    private static int sourceExpectedStatusParam(int statusId, int index, int fallback) {
        BattleStatusRow row = VqsvBattleTables.instance().status(statusId);
        return row == null ? fallback : VqsvBattleTables.get(row.raw, index, fallback);
    }

    private static int sourceExpectedHeldItemParam(int itemId, int index, int fallback) {
        BattleHeldItemRow row = VqsvBattleTables.instance().heldItem(itemId);
        return row == null ? fallback : VqsvBattleTables.get(row.raw, index, fallback);
    }

    private static int sourceExpectedPostExpPassiveHeal(int speciesId) {
        BattleSpeciesRow species = VqsvBattleTables.instance().species(speciesId);
        short[] passiveRow = VqsvBattleTables.instance().row(2, 0);
        int baseHp = species == null ? 0 : VqsvBattleTables.get(species.raw, 5, 0);
        int percent = VqsvBattleTables.get(passiveRow, 6, 0);
        return Math.max(0, baseHp * percent / 100);
    }

    private static int sourcePetExp(SourcePetState pet) {
        return pet != null && pet.sourcePayload != null && pet.sourcePayload.length > 7
                ? pet.sourcePayload[7]
                : 0;
    }

    private static void assertSourcePetExp(SourcePetState pet, int expected, String label) {
        int actual = sourcePetExp(pet);
        if (actual != expected) {
            throw new IllegalStateException(label + " EXP mismatch expected="
                    + expected + " actual=" + actual
                    + " species=" + (pet == null ? -1 : pet.speciesId)
                    + " level=" + (pet == null ? -1 : pet.level)
                    + " payload=" + (pet == null ? "null" : java.util.Arrays.toString(pet.sourcePayload)));
        }
    }

    private static SourcePetState setupNormalP8ExpInitialFrame(VqsvIntroDemo.Scene s, String label) {
        s.eventIndex = s.events.size();
        SourcePetState pet = new SourcePetState(0, 17, 7, 3, 2, 10, 45);
        pet.sourcePayload[7] = 0;
        s.sourcePets.add(pet);
        SourceBattleRuntime runtime = new SourceBattleRuntime(52, new int[]{68, 5, 1},
                new int[0], new int[]{0, 2}, new int[]{10, 10, 0}, 0, true);
        s.current = runtime;
        tickUntilBattleState(s, "P20", 120);
        runtime.debugQueueDebuffForSmoke(s, false, 0, 40, 1, 1, 1);
        int guard = 0;
        while ((!"P8".equals(s.battleStateName)
                || !"levelup".equals(s.battleUiMode)
                || s.battleLevelUpView == null
                || s.battleLevelUpView.leveled)
                && guard++ < 360) {
            s.tick();
        }
        if (!"P8".equals(s.battleStateName)
                || !"levelup".equals(s.battleUiMode)
                || s.battleLevelUpView == null
                || s.battleLevelUpView.leveled
                || s.battleLevelUpView.expValue != 0
                || !traceContains(s, "game.h.a initial render before game.h.am")) {
            throw new IllegalStateException(label + " expected P8 frame0 EXP"
                    + " state=" + s.battleStateName
                    + " ui=" + s.battleUiMode
                    + " value=" + (s.battleLevelUpView == null ? -1 : s.battleLevelUpView.expValue)
                    + " trace=" + tailTrace(s, 28));
        }
        return pet;
    }

    private static void handleBattleExpP8AnimationCheckpoint(VqsvIntroDemo.Scene s, String checkpoint) {
        SourcePetState pet = setupNormalP8ExpInitialFrame(s, checkpoint);
        int expected = sourceExpectedExpAward(5, 1, 7, 1);
        int expectedValue = 0;
        if ("battle_exp_p8_frame1".equals(checkpoint)) {
            s.tick();
            expectedValue = 8;
        } else if ("battle_exp_p8_mid".equals(checkpoint)) {
            for (int i = 0; i < 10; i++) {
                s.tick();
            }
            expectedValue = 80;
        } else if ("battle_exp_p8_target_hold".equals(checkpoint)) {
            int guard = 0;
            while (s.battleLevelUpView != null
                    && s.battleLevelUpView.expValue < expected
                    && guard++ < 120) {
                s.tick();
            }
            expectedValue = expected;
        }
        if (!"P8".equals(s.battleStateName)
                || !"levelup".equals(s.battleUiMode)
                || s.battleLevelUpView == null
                || s.battleLevelUpView.leveled
                || s.battleLevelUpView.expValue != expectedValue
                || traceContains(s, "P22 game.h.an/ao levelUp")) {
            throw new IllegalStateException(checkpoint + " expected P8 EXP value="
                    + expectedValue
                    + " actual=" + (s.battleLevelUpView == null ? -1 : s.battleLevelUpView.expValue)
                    + " state=" + s.battleStateName
                    + " ui=" + s.battleUiMode
                    + " trace=" + tailTrace(s, 30));
        }
        assertSourcePetExp(pet, expected, checkpoint + " source EXP commit");
        assertP8ExpPosMidRow0(s, checkpoint + " pos.mid");
        s.sourceStateTrace.add("SMOKE verified " + checkpoint
                + " expValue=" + expectedValue
                + " target=" + expected);
    }

    static void tickUntilBattleP7Phase(VqsvIntroDemo.Scene s, int phase, int maxTicks) {
        int guard = 0;
        while (!"P7".equals(s.battleStateName) || s.battleP7Phase != phase) {
            if (guard++ >= maxTicks) {
                throw new IllegalStateException("Battle P7 phase " + phase
                        + " not reached in " + maxTicks
                        + " ticks, current=" + s.battleStateName
                        + " phase=" + s.battleP7Phase);
            }
            s.tick();
        }
    }

    private static boolean isSkill10DirectAnimationCheckpoint(String checkpoint) {
        return "battle_skill10_direct_before".equals(checkpoint)
                || "battle_skill10_direct_attacker_action_gate".equals(checkpoint)
                || "battle_skill10_direct_actor_u21_start".equals(checkpoint)
                || "battle_skill10_direct_damage_frame".equals(checkpoint)
                || "battle_skill10_direct_hp_settled".equals(checkpoint)
                || "battle_skill10_direct_finish".equals(checkpoint);
    }

    private static void handleSkill10DirectAnimationCheckpoint(VqsvIntroDemo.Scene s, String checkpoint) {
        if ("battle_skill10_direct_before".equals(checkpoint)) {
            SourceBattleRuntime runtime = enterElderP3Skill10BeforeConfirm(s);
            assertSkill10SourceRows(s, checkpoint);
            assertSkill10P3BeforeConfirm(s, runtime, checkpoint);
            s.sourceStateTrace.add("SMOKE verified skill10 Diệp Toàn before"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " effectRow=" + java.util.Arrays.toString(VqsvBattleAnimationTables.instance().effectRow(10)));
            return;
        }

        enterElderP7WithSkills(s, new int[]{10, 45}, 0);
        SourceBattleRuntime runtime = (SourceBattleRuntime) s.current;
        runtime.debugSetNextP7HitRollForSmoke(99);
        assertSkill10SourceRows(s, checkpoint);

        if ("battle_skill10_direct_attacker_action_gate".equals(checkpoint)) {
            tickUntilBattleP7AttackerActionGate(s, 120, 10);
            assertP7AttackerActionGateBeforeEffect(s, runtime, checkpoint, 10);
            s.sourceStateTrace.add("SMOKE verified skill10 direct attacker action gate before target effect"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " baseState=" + s.battleP7BaseStatePlayerSide
                    + " baseCursor=" + s.battleP7BaseCursorPlayerSide
                    + " actorVisible=" + s.battleP7ActorEffectVisible);
            return;
        }

        if ("battle_skill10_direct_actor_u21_start".equals(checkpoint)) {
            tickUntilBattleP7Phase(s, 1, 120);
            for (int i = 0; i < 20 && !s.battleP7ActorEffectVisible; i++) {
                s.tick();
            }
            assertSkill10P7ActorVisible(s, runtime, checkpoint);
            s.sourceStateTrace.add("SMOKE verified skill10 Diệp Toàn actor"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " actorSprite=" + s.battleP7ActorEffectSpriteId
                    + " actorState=" + s.battleP7ActorEffectState
                    + " actorCursor=" + s.battleP7ActorEffectCursor
                    + " side=" + (s.battleP7ActorEffectOnPlayerSide ? "player" : "enemy"));
            return;
        }

        tickUntilBattleP7Phase(s, 2, 160);
        int damage = latestTraceDamage(s, "battle P7 damage frame skill=10");
        if ("battle_skill10_direct_damage_frame".equals(checkpoint)) {
            assertSkill10DamageFrame(s, runtime, checkpoint, damage);
            s.sourceStateTrace.add("SMOKE verified skill10 Diệp Toàn damage frame"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " damage=" + damage
                    + " damageText=" + s.battleP7DamageText
                    + " actorVisible=" + s.battleP7ActorEffectVisible);
            return;
        }

        int expectedEnemyHp = Math.max(0, s.battleEnemyMaxHp - damage);
        int guard = 0;
        while ("P7".equals(s.battleStateName)
                && s.battleEnemyHp > expectedEnemyHp
                && guard++ < 240) {
            s.tick();
        }
        if (s.battleEnemyHp > expectedEnemyHp
                || runtime.debugPlayerSkillPpForSmoke(0) != 44
                || damage <= 0
                || !traceContains(s, "battle P7 source n() skill=10")
                || !traceContains(s, "battle P7 actor u.a() start skill=10")
                || !traceContains(s, "battle P7 damage frame skill=10")) {
            throw new IllegalStateException(checkpoint + " expected skill10 HP display to settle after damage"
                    + " state=" + s.battleStateName
                    + " phase=" + s.battleP7Phase
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " expectedHp=" + expectedEnemyHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " damage=" + damage
                    + " trace=" + tailTrace(s, 36));
        }
        s.sourceStateTrace.add("SMOKE verified skill10 Diệp Toàn finish"
                + " state=" + s.battleStateName
                + " phase=" + s.battleP7Phase
                + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                + " expectedEnemyHp=" + expectedEnemyHp
                + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                + " damage=" + damage
                + " actorVisible=" + s.battleP7ActorEffectVisible);
    }

    private static SourceBattleRuntime enterElderP3Skill10BeforeConfirm(VqsvIntroDemo.Scene s) {
        s.eventIndex = s.events.size();
        s.sourcePets.add(new SourcePetState(0, 17, 7, 3, 2, 10, 45));
        SourceBattleRuntime runtime = new SourceBattleRuntime(52, new int[]{68, 5, 1},
                new int[0], new int[]{0, 2}, new int[]{10, 10, 0}, 0, true);
        s.current = runtime;
        tickUntilBattleState(s, "P20", 120);
        s.battleClickX = 20;
        s.battleClickY = 300;
        tickUntilBattleState(s, "P3", 80);
        for (int i = 0; i < 10; i++) {
            s.tick();
        }
        return runtime;
    }

    private static void assertSkill10SourceRows(VqsvIntroDemo.Scene s, String checkpoint) {
        BattleSkillRow row = VqsvBattleTables.instance().skill(10);
        byte[] effect = VqsvBattleAnimationTables.instance().effectRow(10);
        if (row == null
                || row.powerPercent != 100
                || row.ppMax != 45
                || row.effectMode != 0
                || row.effectId != -1
                || row.targetSide != 0
                || !java.util.Arrays.equals(effect, new byte[]{0, 0, 21, 0, -1, -1, 0})) {
            throw new IllegalStateException(checkpoint + " skill10 source row mismatch"
                    + " skill=" + (row == null ? "null" : java.util.Arrays.toString(row.raw))
                    + " effect=" + java.util.Arrays.toString(effect));
        }
        s.sourceStateTrace.add("SMOKE verified skill10 source rows aq.c[1][10]="
                + java.util.Arrays.toString(row.raw)
                + " effect.mid[10]=" + java.util.Arrays.toString(effect)
                + " name=" + row.name("skill10"));
    }

    private static void assertSkill10P3BeforeConfirm(VqsvIntroDemo.Scene s, SourceBattleRuntime runtime,
                                                     String checkpoint) {
        if (!"P3".equals(s.battleStateName)
                || s.battleSkillIds.length == 0
                || s.battleSkillIds[0] != 10
                || runtime.debugPlayerSkillPpForSmoke(0) != 45
                || s.battleEnemyHp != s.battleEnemyMaxHp
                || s.battleP7ActorEffectVisible
                || s.battleP7DamageVisible) {
            throw new IllegalStateException(checkpoint + " expected P3 pre-confirm skill10 snapshot"
                    + " state=" + s.battleStateName
                    + " skills=" + java.util.Arrays.toString(s.battleSkillIds)
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " actor=" + s.battleP7ActorEffectVisible
                    + " damageVisible=" + s.battleP7DamageVisible
                    + " trace=" + tailTrace(s, 24));
        }
    }

    private static void assertSkill10P7ActorVisible(VqsvIntroDemo.Scene s, SourceBattleRuntime runtime,
                                                    String checkpoint) {
        if (!s.battleP7ActorEffectVisible
                || s.battleP7ActorEffectSpriteId != 263
                || s.battleP7ActorEffectState != 0
                || s.battleP7ActorEffectOnPlayerSide
                || s.battleEnemyHp != s.battleEnemyMaxHp
                || runtime.debugPlayerSkillPpForSmoke(0) != 44
                || !traceContains(s, "battle P7 source n() skill=10")
                || !traceContains(s, "id=21")
                || !traceContains(s, "param=0")
                || !traceContains(s, "battle P7 actor u.a() start skill=10")
                || traceContains(s, "battle P7 damage frame skill=10")) {
            throw new IllegalStateException(checkpoint + " expected skill10 actor u21 before damage"
                    + " actorVisible=" + s.battleP7ActorEffectVisible
                    + " actorSprite=" + s.battleP7ActorEffectSpriteId
                    + " actorState=" + s.battleP7ActorEffectState
                    + " actorCursor=" + s.battleP7ActorEffectCursor
                    + " actorSidePlayer=" + s.battleP7ActorEffectOnPlayerSide
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " trace=" + tailTrace(s, 36));
        }
    }

    private static void assertSkill10DamageFrame(VqsvIntroDemo.Scene s, SourceBattleRuntime runtime,
                                                 String checkpoint, int damage) {
        if (!s.battleP7DamageVisible
                || s.battleP7DamageText.isEmpty()
                || !s.battleP7MissText.isEmpty()
                || s.battleP7ActorEffectVisible
                || runtime.debugPlayerSkillPpForSmoke(0) != 44
                || damage <= 0
                || s.battleEnemyHp != s.battleEnemyMaxHp
                || !traceContains(s, "battle P7 damage frame skill=10")
                || !traceContains(s, "hit=true")
                || !traceContains(s, "sideEffectsCommitted=true")) {
            throw new IllegalStateException(checkpoint + " expected skill10 damage frame"
                    + " visible=" + s.battleP7DamageVisible
                    + " damageText=" + s.battleP7DamageText
                    + " missText=" + s.battleP7MissText
                    + " actorVisible=" + s.battleP7ActorEffectVisible
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " damage=" + damage
                    + " trace=" + tailTrace(s, 36));
        }
    }

    private static boolean isDirectBaseOneChunkCheckpoint(String checkpoint) {
        int skillId = directBaseSkillIdFromCheckpoint(checkpoint);
        if (!isDirectBaseOneChunkSkill(skillId)) {
            return false;
        }
        return checkpoint.equals(directBaseCheckpointName(skillId, "before"))
                || checkpoint.equals(directBaseCheckpointName(skillId, "attacker_action_gate"))
                || checkpoint.equals(directBaseActorCheckpointName(skillId))
                || checkpoint.equals(directBaseCheckpointName(skillId, "damage_frame"))
                || checkpoint.equals(directBaseCheckpointName(skillId, "hp_settled"));
    }

    private static void handleDirectBaseOneChunkCheckpoint(VqsvIntroDemo.Scene s, String checkpoint) {
        int skillId = directBaseSkillIdFromCheckpoint(checkpoint);
        int effectId = directBaseActorEffectId(skillId);
        if (checkpoint.equals(directBaseCheckpointName(skillId, "before"))) {
            SourceBattleRuntime runtime = enterElderP3DirectBaseBeforeConfirm(s, skillId);
            assertDirectBaseSourceRows(s, checkpoint, skillId);
            assertDirectBaseP3BeforeConfirm(s, runtime, checkpoint, skillId);
            s.sourceStateTrace.add("SMOKE verified direct-base skill" + skillId + " before"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " effectRow=" + java.util.Arrays.toString(VqsvBattleAnimationTables.instance().effectRow(skillId)));
            return;
        }

        enterElderP7WithSkills(s, new int[]{skillId, 45}, 0);
        SourceBattleRuntime runtime = (SourceBattleRuntime) s.current;
        runtime.debugSetNextP7HitRollForSmoke(99);
        assertDirectBaseSourceRows(s, checkpoint, skillId);

        if (checkpoint.equals(directBaseCheckpointName(skillId, "attacker_action_gate"))) {
            tickUntilBattleP7AttackerActionGate(s, 120, skillId);
            assertP7AttackerActionGateBeforeEffect(s, runtime, checkpoint, skillId);
            s.sourceStateTrace.add("SMOKE verified direct-base skill" + skillId
                    + " attacker action gate before target effect"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " baseState=" + s.battleP7BaseStatePlayerSide
                    + " baseCursor=" + s.battleP7BaseCursorPlayerSide
                    + " actorVisible=" + s.battleP7ActorEffectVisible);
            return;
        }

        if (checkpoint.equals(directBaseActorCheckpointName(skillId))) {
            tickUntilBattleP7Phase(s, 1, 120);
            for (int i = 0; i < 20 && !s.battleP7ActorEffectVisible; i++) {
                s.tick();
            }
            assertDirectBaseP7ActorVisible(s, runtime, checkpoint, skillId);
            s.sourceStateTrace.add("SMOKE verified direct-base skill" + skillId + " actor"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " actorEffect=" + effectId
                    + " actorSprite=" + s.battleP7ActorEffectSpriteId
                    + " actorState=" + s.battleP7ActorEffectState
                    + " actorCursor=" + s.battleP7ActorEffectCursor
                    + " side=" + (s.battleP7ActorEffectOnPlayerSide ? "player" : "enemy"));
            return;
        }

        tickUntilBattleP7Phase(s, 2, 160);
        int damage = latestTraceDamage(s, "battle P7 damage frame skill=" + skillId);
        if (checkpoint.equals(directBaseCheckpointName(skillId, "damage_frame"))) {
            assertDirectBaseDamageFrame(s, runtime, checkpoint, skillId, damage);
            s.sourceStateTrace.add("SMOKE verified direct-base skill" + skillId + " damage frame"
                    + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                    + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " damage=" + damage
                    + " damageText=" + s.battleP7DamageText
                    + " actorVisible=" + s.battleP7ActorEffectVisible);
            return;
        }

        int expectedEnemyHp = Math.max(0, s.battleEnemyMaxHp - damage);
        int guard = 0;
        while ("P7".equals(s.battleStateName)
                && s.battleEnemyHp > expectedEnemyHp
                && guard++ < 240) {
            s.tick();
        }
        if (s.battleEnemyHp > expectedEnemyHp
                || runtime.debugPlayerSkillPpForSmoke(0) != 44
                || damage <= 0
                || !traceContains(s, "battle P7 source n() skill=" + skillId)
                || !traceContains(s, "battle P7 actor u.a() start skill=" + skillId)
                || !traceContains(s, "battle P7 damage frame skill=" + skillId)) {
            throw new IllegalStateException(checkpoint + " expected direct-base skill" + skillId
                    + " HP display to settle after damage"
                    + " state=" + s.battleStateName
                    + " phase=" + s.battleP7Phase
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " expectedHp=" + expectedEnemyHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " damage=" + damage
                    + " trace=" + tailTrace(s, 36));
        }
        s.sourceStateTrace.add("SMOKE verified direct-base skill" + skillId + " hp settled"
                + " state=" + s.battleStateName
                + " phase=" + s.battleP7Phase
                + " hp=" + s.battlePlayerHp + "/" + s.battlePlayerMaxHp
                + ":" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                + " expectedEnemyHp=" + expectedEnemyHp
                + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                + " damage=" + damage
                + " actorVisible=" + s.battleP7ActorEffectVisible);
    }

    private static int parsePlusText(String text) {
        if (text == null || text.length() < 2 || text.charAt(0) != '+') {
            return -1;
        }
        try {
            return Integer.parseInt(text.substring(1));
        } catch (NumberFormatException ex) {
            return -1;
        }
    }

    private static String directTimelinePngName(int skillId, String suffix) {
        return "battle_skill" + skillId + "_direct_timeline_" + suffix + ".png";
    }

    private static void writeScenePng(VqsvIntroDemo.Scene s, java.io.File out) throws java.io.IOException {
        BufferedImage img = new BufferedImage(W, H, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        s.render(g);
        g.dispose();
        ImageIO.write(img, "png", out);
    }

    private static SourceBattleRuntime enterElderP3DirectBaseBeforeConfirm(VqsvIntroDemo.Scene s, int skillId) {
        s.eventIndex = s.events.size();
        s.sourcePets.add(new SourcePetState(0, 17, 7, 3, 2, skillId, 45));
        SourceBattleRuntime runtime = new SourceBattleRuntime(52, new int[]{68, 5, 1},
                new int[0], new int[]{0, 2}, new int[]{10, 10, 0}, 0, true);
        s.current = runtime;
        tickUntilBattleState(s, "P20", 120);
        s.battleClickX = 20;
        s.battleClickY = 300;
        tickUntilBattleState(s, "P3", 80);
        for (int i = 0; i < 10; i++) {
            s.tick();
        }
        return runtime;
    }

    private static void assertDirectBaseSourceRows(VqsvIntroDemo.Scene s, String checkpoint, int skillId) {
        BattleSkillRow row = VqsvBattleTables.instance().skill(skillId);
        byte[] effect = VqsvBattleAnimationTables.instance().effectRow(skillId);
        byte[] expectedEffect = directBaseExpectedEffectRow(skillId);
        if (row == null
                || row.powerPercent != directBaseExpectedPower(skillId)
                || row.ppMax != directBaseExpectedPp(skillId)
                || row.effectMode != 0
                || row.effectId != -1
                || row.chanceOrParam != -1
                || row.targetSide != 0
                || !java.util.Arrays.equals(effect, expectedEffect)) {
            throw new IllegalStateException(checkpoint + " direct-base skill" + skillId + " source row mismatch"
                    + " skill=" + (row == null ? "null" : java.util.Arrays.toString(row.raw))
                    + " effect=" + java.util.Arrays.toString(effect)
                    + " expectedEffect=" + java.util.Arrays.toString(expectedEffect));
        }
        s.sourceStateTrace.add("SMOKE verified direct-base source rows skill" + skillId
                + " aq.c[1]=" + java.util.Arrays.toString(row.raw)
                + " effect.mid=" + java.util.Arrays.toString(effect)
                + " name=" + row.name("skill" + skillId));
    }

    private static void assertDirectBaseP3BeforeConfirm(VqsvIntroDemo.Scene s, SourceBattleRuntime runtime,
                                                       String checkpoint, int skillId) {
        if (!"P3".equals(s.battleStateName)
                || s.battleSkillIds.length == 0
                || s.battleSkillIds[0] != skillId
                || runtime.debugPlayerSkillPpForSmoke(0) != directBaseExpectedPp(skillId)
                || s.battleEnemyHp != s.battleEnemyMaxHp
                || s.battleP7ActorEffectVisible
                || s.battleP7DamageVisible) {
            throw new IllegalStateException(checkpoint + " expected P3 pre-confirm direct-base skill" + skillId
                    + " state=" + s.battleStateName
                    + " skills=" + java.util.Arrays.toString(s.battleSkillIds)
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " actor=" + s.battleP7ActorEffectVisible
                    + " damageVisible=" + s.battleP7DamageVisible
                    + " trace=" + tailTrace(s, 24));
        }
    }

    private static void assertDirectBaseP7ActorVisible(VqsvIntroDemo.Scene s, SourceBattleRuntime runtime,
                                                       String checkpoint, int skillId) {
        int effectId = directBaseActorEffectId(skillId);
        if (!s.battleP7ActorEffectVisible
                || s.battleP7ActorEffectSpriteId != directBaseActorSpriteId(skillId)
                || s.battleP7ActorEffectState != directBaseActorState(skillId)
                || s.battleP7ActorEffectOnPlayerSide
                || s.battleEnemyHp != s.battleEnemyMaxHp
                || runtime.debugPlayerSkillPpForSmoke(0) != directBaseExpectedPpAfterUse(skillId)
                || !traceContains(s, "battle P7 source n() skill=" + skillId)
                || !traceContains(s, "id=" + effectId)
                || !traceContains(s, "param=" + directBaseActorState(skillId))
                || !traceContains(s, "battle P7 actor u.a() start skill=" + skillId)
                || traceContains(s, "battle P7 damage frame skill=" + skillId)) {
            throw new IllegalStateException(checkpoint + " expected direct-base skill" + skillId + " actor"
                    + " actorVisible=" + s.battleP7ActorEffectVisible
                    + " actorSprite=" + s.battleP7ActorEffectSpriteId
                    + " actorState=" + s.battleP7ActorEffectState
                    + " actorCursor=" + s.battleP7ActorEffectCursor
                    + " actorSidePlayer=" + s.battleP7ActorEffectOnPlayerSide
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " trace=" + tailTrace(s, 36));
        }
    }

    private static void tickUntilBattleP7AttackerActionGate(VqsvIntroDemo.Scene s, int maxTicks, int skillId) {
        int guard = 0;
        while (!traceContains(s, "battle P7 attacker state1 gate before target effect skill=" + skillId)) {
            if (guard++ >= maxTicks) {
                throw new IllegalStateException("Battle P7 attacker action gate timeout skill=" + skillId
                        + " state=" + s.battleStateName
                        + " phase=" + s.battleP7Phase
                        + " baseState=" + s.battleP7BaseStatePlayerSide
                        + " baseCursor=" + s.battleP7BaseCursorPlayerSide
                        + " actorVisible=" + s.battleP7ActorEffectVisible
                        + " trace=" + tailTrace(s, 36));
            }
            s.tick();
        }
    }

    private static void assertP7AttackerActionGateBeforeEffect(VqsvIntroDemo.Scene s, SourceBattleRuntime runtime,
                                                               String checkpoint, int skillId) {
        if (!"P7".equals(s.battleStateName)
                || s.battleP7Phase != 1
                || !s.battleP7AttackerPlayerSide
                || s.battleP7BaseStatePlayerSide != 1
                || s.battleP7BaseCursorPlayerSide < 1
                || s.battleP7ActorEffectVisible
                || s.battleP7SpecialVisible
                || s.battleP7DamageVisible
                || s.battleEnemyHp != s.battleEnemyMaxHp
                || runtime.debugPlayerSkillPpForSmoke(0) != directBaseExpectedPpAfterUse(skillId)
                || !traceContains(s, "battle P7 source n() skill=" + skillId)
                || !traceContains(s, "battle P7 attacker state1 gate before target effect skill=" + skillId)
                || traceContains(s, "battle P7 actor u.a() start skill=" + skillId)
                || traceContains(s, "battle P7 damage frame skill=" + skillId)) {
            throw new IllegalStateException(checkpoint + " expected attacker state1 gate before target effect"
                    + " state=" + s.battleStateName
                    + " phase=" + s.battleP7Phase
                    + " attackerPlayer=" + s.battleP7AttackerPlayerSide
                    + " baseState=" + s.battleP7BaseStatePlayerSide
                    + " baseCursor=" + s.battleP7BaseCursorPlayerSide
                    + " actorVisible=" + s.battleP7ActorEffectVisible
                    + " specialVisible=" + s.battleP7SpecialVisible
                    + " damageVisible=" + s.battleP7DamageVisible
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " trace=" + tailTrace(s, 36));
        }
    }

    private static void assertDirectBaseDamageFrame(VqsvIntroDemo.Scene s, SourceBattleRuntime runtime,
                                                    String checkpoint, int skillId, int damage) {
        if (!s.battleP7DamageVisible
                || s.battleP7DamageText.isEmpty()
                || !s.battleP7MissText.isEmpty()
                || s.battleP7ActorEffectVisible
                || runtime.debugPlayerSkillPpForSmoke(0) != directBaseExpectedPpAfterUse(skillId)
                || damage <= 0
                || s.battleEnemyHp != s.battleEnemyMaxHp
                || !traceContains(s, "battle P7 damage frame skill=" + skillId)
                || !traceContains(s, "hit=true")
                || !traceContains(s, "sideEffectsCommitted=true")) {
            throw new IllegalStateException(checkpoint + " expected direct-base skill" + skillId + " damage frame"
                    + " visible=" + s.battleP7DamageVisible
                    + " damageText=" + s.battleP7DamageText
                    + " missText=" + s.battleP7MissText
                    + " actorVisible=" + s.battleP7ActorEffectVisible
                    + " hp=" + s.battleEnemyHp + "/" + s.battleEnemyMaxHp
                    + " pp=" + runtime.debugPlayerSkillPpForSmoke(0)
                    + " damage=" + damage
                    + " trace=" + tailTrace(s, 36));
        }
    }

    private static int directBaseSkillIdFromCheckpoint(String checkpoint) {
        String prefix = "battle_skill";
        String marker = "_direct_";
        if (!checkpoint.startsWith(prefix)) {
            return -1;
        }
        int end = checkpoint.indexOf(marker, prefix.length());
        if (end < 0) {
            return -1;
        }
        try {
            return Integer.parseInt(checkpoint.substring(prefix.length(), end));
        } catch (NumberFormatException ex) {
            return -1;
        }
    }

    private static boolean isDirectBaseOneChunkSkill(int skillId) {
        return skillId == 0 || skillId == 20 || skillId == 30 || skillId == 40 || skillId == 60;
    }

    private static String directBaseCheckpointName(int skillId, String suffix) {
        return "battle_skill" + skillId + "_direct_" + suffix;
    }

    private static String directBaseActorCheckpointName(int skillId) {
        return "battle_skill" + skillId + "_direct_actor_u" + directBaseActorEffectId(skillId) + "_start";
    }

    private static byte[] directBaseExpectedEffectRow(int skillId) {
        return new byte[]{0, 0, (byte) directBaseActorEffectId(skillId),
                (byte) directBaseActorState(skillId), -1, -1, 0};
    }

    private static int directBaseActorEffectId(int skillId) {
        switch (skillId) {
            case 0:
            case 1:
            case 2:
            case 3:
            case 6:
            case 7:
            case 8:
            case 9:
                return 20;
            case 10:
            case 16:
            case 18:
            case 19:
                return 21;
            case 20:
                return 22;
            case 30:
                return 23;
            case 40:
                return 24;
            case 60:
                return 26;
            default:
                throw new IllegalArgumentException("Not a one-chunk direct-base smoke skill: " + skillId);
        }
    }

    private static int directBaseActorSpriteId(int skillId) {
        return directBaseActorEffectId(skillId) + 242;
    }

    private static int directBaseActorState(int skillId) {
        if (skillId >= 10 && skillId <= 19) {
            return 1;
        }
        return 0;
    }

    private static int directBaseExpectedPower(int skillId) {
        switch (skillId) {
            case 9:
                return 200;
            case 6:
            case 16:
            case 26:
            case 36:
            case 46:
            case 56:
            case 66:
                return 150;
            default:
                return 100;
        }
    }

    private static int directBaseExpectedPp(int skillId) {
        if (skillId == 3) {
            return 30;
        }
        if (skillId == 9) {
            return 15;
        }
        return directBaseExpectedPower(skillId) == 150 ? 30 : 45;
    }

    private static int directBaseExpectedPpAfterUse(int skillId) {
        return Math.max(0, directBaseExpectedPp(skillId) - 1);
    }

